svg.script:
(() => {
  const root = document.currentScript.ownerSVGElement;
  const cuts = Array.from(root.querySelectorAll('[data-cut]'));
  const shapes = Array.from(root.querySelectorAll('[data-hit-shape]'));
  const original = new Map(shapes.map(el => [el, {stroke: el.getAttribute('stroke'), width: el.getAttribute('stroke-width'), fill: el.getAttribute('fill')} ]));
  const related = { Forequarter: ['goat-neck', 'goat-shoulder', 'goat-rack-rib'], Hindquarter: ['goat-loin', 'goat-leg'] };
  function accent(shape) {
    shape.setAttribute('stroke', '#781f23'); shape.setAttribute('stroke-width', original.get(shape).width);
    if (shape.localName === 'rect') shape.setAttribute('fill', '#f4e7e7');
  }
  function select(target) {
    shapes.forEach(shape => { const state = original.get(shape); shape.setAttribute('stroke',state.stroke); shape.setAttribute('stroke-width',state.width); shape.setAttribute('fill',state.fill); });
    cuts.forEach(el => { const active = el === target; el.classList.toggle('is-selected',active); el.setAttribute('aria-pressed',String(active)); });
    target.querySelectorAll('[data-hit-shape]').forEach(accent);
    const cut = target.getAttribute('data-cut');
    (related[cut] || []).forEach(id => root.querySelector('#'+id).querySelectorAll('[data-hit-shape]').forEach(accent));
    const quarter = cut === 'Forequarter' ? 'fore' : cut === 'Hindquarter' ? 'hind' : null;
    if (quarter) root.querySelectorAll('[data-quarter="'+quarter+'"]').forEach(accent);
    root.dispatchEvent(new CustomEvent('cutlink:cut-selected',{bubbles:true,composed:true,detail:{animal:'Goat',id:target.id,cut,subcuts:target.getAttribute('data-subcuts').split(',')}}));
  }
  cuts.forEach((el,index) => {
    el.addEventListener('click',() => select(el));
    el.addEventListener('keydown',event => {
      if (event.key === 'Enter' || event.key === ' ') {event.preventDefault();select(el);}
      else if (['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(event.key)) {
        event.preventDefault();
        const next = event.key === 'Home' ? 0 : event.key === 'End' ? cuts.length-1 : (index+(['ArrowRight','ArrowDown'].includes(event.key)?1:-1)+cuts.length)%cuts.length;
        cuts[next].focus();
      }
    });
  });
})();
